import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const root = new URL("../", import.meta.url);
const catalog = JSON.parse(
  await readFile(new URL("packages/contracts/telemetry.json", root), "utf8"),
);
const banner =
  "// Generated by scripts/generate-telemetry.mjs; edit packages/contracts/telemetry.json.\n";
for (const [name, event] of Object.entries(catalog.events)) {
  if (!/^[a-z]+\.[a-z_]+$/.test(name))
    throw new Error(`Invalid event: ${name}`);
  for (const property of event.properties)
    if (!(property in catalog.properties))
      throw new Error(`Unknown property: ${property}`);
}
const swift = `${banner}import Foundation\n\nenum TelemetryEventName: String, CaseIterable {\n${Object.keys(
  catalog.events,
)
  .map(
    (name) =>
      `    case ${name.replace(/\.([a-z])/g, (_, c) => c.toUpperCase()).replace(/_([a-z])/g, (_, c) => c.toUpperCase())} = "${name}"`,
  )
  .join(
    "\n",
  )}\n}\n\nenum TelemetryContract {\n    static let version = ${catalog.version}\n${Object.entries(
  catalog.limits,
)
  .map(([key, value]) => `    static let ${key} = ${value}`)
  .join(
    "\n",
  )}\n    static let json = #"""\n${JSON.stringify(catalog)}\n"""#\n    static let catalog = try! JSONSerialization.jsonObject(with: Data(json.utf8)) as! [String: Any]\n}\n`;
const outputs = new Map([
  [
    "packages/telemetry/catalog.generated.ts",
    `${banner}export const catalog = ${JSON.stringify(catalog, null, 2)} as const;\nexport type EventName = keyof typeof catalog.events;\nexport type Platform = typeof catalog.platforms[number];\n`,
  ],
  ["apps/ios/Shared/Telemetry.generated.swift", swift],
]);
let stale = false;
for (const [name, content] of outputs) {
  const url = new URL(name, root);
  if ((await readFile(url, "utf8").catch(() => "")) === content) continue;
  if (process.argv.includes("--check")) {
    console.error(`Telemetry export is stale: ${name}`);
    stale = true;
  } else await writeFile(fileURLToPath(url), content);
}
if (stale) process.exitCode = 1;
